 367→+func newTraceCmd() *cobra.Command {
 368→+	var last int
 369→+	var hookFilter string
 370→+
 371→+	cmd := &cobra.Command{
 372→+		Use:   "trace",
 373→+		Short: "Show hook performance traces",
 374→+		Long: `Show timing information for recent hook invocations.
 375→+
 376→+Traces are emitted at DEBUG log level. To enable them, either:
 377→+  - Set ENTIRE_LOG_LEVEL=DEBUG in your shell profile
 378→+  - Add "log_level": "DEBUG" to .entire/settings.json
 379→+
 380→+Examples:
 381→+  entire trace                     Show the most recent hook trace
 382→+  entire trace --last 5            Show the last 5 hook traces
 383→+  entire trace --hook post-commit  Show only post-commit hook traces`,
 384→+		RunE: func(cmd *cobra.Command, _ []string) error {
 385→+			if last < 1 {
 386→+				return fmt.Errorf("--last must be at least 1, got %d", last)
 387→+			}
 388→+
 389→+			repoRoot, err := paths.WorktreeRoot(cmd.Context())
 390→+			if err != nil {
 391→+				cmd.SilenceUsage = true
 392→+				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
 393→+				return NewSilentError(fmt.Errorf("not a git repository: %w", err))
 394→+			}
 395→+
 396→+			logFile := filepath.Join(repoRoot, logging.LogsDir, "entire.log")
 397→+
 398→+			entries, err := collectTraceEntries(logFile, last, hookFilter)
 399→+			if err != nil {
 400→+				return fmt.Errorf("collecting trace entries: %w", err)
 401→+			}
 402→+
 403→+			renderTraceEntries(cmd.OutOrStdout(), entries)
 404→+			return nil
 405→+		},
 406→+	}
 407→+
 408→+	cmd.Flags().IntVar(&last, "last", 1, "Show last N hook invocations")
 409→+	cmd.Flags().StringVar(&hookFilter, "hook", "", "Filter by hook type (e.g. post-commit, prepare-commit-msg, pre-push)")
 410→+
 411→+	return cmd
 412→+}
