 716→+func TestParseTraceEntry_SubStepNumericOrdering(t *testing.T) {
 717→+	t.Parallel()
 718→+
 719→+	// Build a trace entry with 12 sub-steps to verify numeric (not lexicographic) ordering.
 720→+	// Lexicographic sort would place .10 and .11 before .2.
 721→+	line := `{"time":"2026-01-15T10:30:00Z","level":"DEBUG","msg":"perf","op":"post-commit","duration_ms":1000,"steps.loop_ms":900,"steps.loop.0_ms":10,"steps.loop.1_ms":20,"steps.loop.2_ms":30,"steps.loop.3_ms":40,"steps.loop.4_ms":50,"steps.loop.5_ms":60,"steps.loop.6_ms":70,"steps.loop.7_ms":80,"steps.loop.8_ms":90,"steps.loop.9_ms":100,"steps.loop.10_ms":110,"steps.loop.11_ms":120}`
 722→+
 723→+	entry := parseTraceEntry(line)
 724→+	if entry == nil {
 725→+		t.Fatal("parseTraceEntry returned nil")
 726→+	}
 727→+
 728→+	if len(entry.Steps) != 1 {
 729→+		t.Fatalf("len(Steps) = %d, want 1", len(entry.Steps))
 730→+	}
 731→+
 732→+	subs := entry.Steps[0].SubSteps
 733→+	if len(subs) != 12 {
 734→+		t.Fatalf("len(SubSteps) = %d, want 12", len(subs))
 735→+	}
 736→+
 737→+	for i, sub := range subs {
 738→+		want := fmt.Sprintf("loop.%d", i)
 739→+		if sub.Name != want {
 740→+			t.Errorf("SubSteps[%d].Name = %q, want %q", i, sub.Name, want)
 741→+		}
