  1→package perf
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"log/slog"
  7→	"time"
  8→
  9→	"github.com/entireio/cli/cmd/entire/cli/logging"
 10→)
 11→
 12→// Span tracks timing for an operation and its substeps.
 13→// A Span is not safe for concurrent use from multiple goroutines.
 14→type Span struct {
 15→	name     string
 16→	start    time.Time
 17→	parent   *Span
 18→	children []*Span
 19→	duration time.Duration
 20→	attrs    []slog.Attr
 21→	ctx      context.Context
 22→	ended    bool
 23→	err      error
 24→}
 25→
 26→// Start begins a new span. If ctx already has a span, the new one becomes a child.
 27→// Returns the updated context and the span. Call span.End() when the operation completes.
 28→func Start(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *Span) {
 29→	parent := spanFromContext(ctx)
 30→	s := &Span{
 31→		name:   name,
 32→		start:  time.Now(),
 33→		parent: parent,
 34→		attrs:  attrs,
 35→		ctx:    ctx,
 36→	}
 37→	if parent != nil {
 38→		parent.children = append(parent.children, s)
 39→	}
 40→	return contextWithSpan(ctx, s), s
 41→}
 42→
 43→// RecordError marks the span as errored. Only the first non-nil error is stored;
 44→// subsequent calls are no-ops. Call this before End() on error paths.
 45→func (s *Span) RecordError(err error) {
 46→	if err == nil || s.err != nil {
 47→		return
 48→	}
 49→	s.err = err
 50→}
 51→
 52→// End completes the span. For root spans, emits a single DEBUG log line
 53→// with the full timing tree. For child spans, records the duration only.
 54→// Safe to call multiple times -- subsequent calls are no-ops.
 55→func (s *Span) End() {
 56→	if s.ended {
 57→		return
 58→	}
 59→	s.ended = true
 60→	s.duration = time.Since(s.start)
 61→
 62→	// Only root spans emit log output
 63→	if s.parent != nil {
 64→		return
 65→	}
 66→
 67→	// Build log attributes: op, duration_ms, error flag, then child step durations.
 68→	// Component is set via context so it appears exactly once in the log line.
 69→	logCtx := logging.WithComponent(s.ctx, "perf")
 70→	grandchildren := 0
 71→	for _, c := range s.children {
 72→		grandchildren += len(c.children)
 73→	}
 74→	attrs := make([]any, 0, 3+2*len(s.children)+2*grandchildren+len(s.attrs))
 75→	attrs = append(attrs, slog.String("op", s.name))
 76→	attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
 77→	if s.err != nil {
 78→		attrs = append(attrs, slog.Bool("error", true))
 79→	}
 80→
 81→	// Add child step durations (and error flags) as flat keys.
 82→	// Disambiguate duplicate child names (from loops) with .1, .2, etc. suffixes
 83→	// to prevent later values from overwriting earlier ones in JSON output.
 84→	//
 85→	// Group spans (children that have their own children) also emit grandchildren
 86→	// with 0-based indexing: steps.<name>.0_ms, steps.<name>.1_ms, etc.
 87→	seen := make(map[string]int, len(s.children))
 88→	for _, child := range s.children {
 89→		// Auto-end children that were not explicitly ended
 90→		if !child.ended {
 91→			child.End()
 92→		}
 93→		stepKey := childStepKey(child.name, seen)
 94→		key := fmt.Sprintf("steps.%s_ms", stepKey)
 95→		attrs = append(attrs, slog.Int64(key, child.duration.Milliseconds()))
 96→		if child.err != nil {
 97→			errKey := fmt.Sprintf("steps.%s_err", stepKey)
 98→			attrs = append(attrs, slog.Bool(errKey, true))
 99→		}
100→
101→		// Emit grandchildren (group iterations) with 0-based indexing
102→		for i, gc := range child.children {
103→			if !gc.ended {
104→				gc.End()
105→			}
106→			gcKey := fmt.Sprintf("steps.%s.%d_ms", stepKey, i)
107→			attrs = append(attrs, slog.Int64(gcKey, gc.duration.Milliseconds()))
108→			if gc.err != nil {
109→				gcErrKey := fmt.Sprintf("steps.%s.%d_err", stepKey, i)
110→				attrs = append(attrs, slog.Bool(gcErrKey, true))
111→			}
112→		}
113→	}
114→
115→	// Add any extra attributes from Start()
116→	for _, a := range s.attrs {
117→		attrs = append(attrs, a)
118→	}
119→
120→	logging.Debug(logCtx, "perf", attrs...)
121→}
122→
123→// childStepKey returns a unique key for a child span name.
124→// First occurrence keeps the original name; subsequent get ~1, ~2, etc.
125→// Uses "~" separator to avoid collision with grandchild "." indexing
126→// (e.g. steps.foo.0_ms for loop iterations).
127→// The seen map is updated in place.
128→func childStepKey(name string, seen map[string]int) string {
129→	n := seen[name]
130→	seen[name] = n + 1
131→	if n == 0 {
132→		return name
133→	}
134→	return fmt.Sprintf("%s~%d", name, n)
135→}
136→
137→// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
138→// creates a child span representing one pass through the loop.
139→//
140→// Usage:
141→//
142→//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
143→//	for _, item := range items {
144→//	    iterCtx, iterSpan := loop.Iteration(ctx)
145→//	    doWork(iterCtx, item)
146→//	    iterSpan.End()
147→//	}
148→//	loop.End()
149→type LoopSpan struct {
150→	span *Span
151→}
152→
153→// StartLoop begins a new loop span. The returned context contains the loop span
154→// and should be passed to Iteration. Call loop.End() after the loop completes.
155→func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
156→	ctx, s := Start(ctx, name, attrs...)
157→	return ctx, &LoopSpan{span: s}
158→}
159→
160→// Iteration creates a child span for a single loop iteration. The caller must
161→// call End() on the returned span when the iteration completes.
162→func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
163→	return Start(ctx, l.span.name)
164→}
165→
166→// End completes the loop span, auto-ending any unended iteration children first
167→// so their durations are captured at loop-end time rather than deferring to the
168→// root span's End() (which may run much later).
169→func (l *LoopSpan) End() {
170→	for _, child := range l.span.children {
171→		if !child.ended {
172→			child.End()
173→		}
174→	}
175→	l.span.End()
176→}
