  1→package cli
  2→
  3→import (
  4→	"bufio"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"io"
  9→	"os"
 10→	"sort"
 11→	"strconv"
 12→	"strings"
 13→	"time"
 14→)
 15→
 16→// traceStep represents a single timed step within a trace span.
 17→// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
 18→type traceStep struct {
 19→	Name       string
 20→	DurationMs int64
 21→	Error      bool
 22→	SubSteps   []traceStep
 23→}
 24→
 25→// traceEntry represents a parsed performance trace log entry.
 26→type traceEntry struct {
 27→	Op         string
 28→	DurationMs int64
 29→	Error      bool
 30→	Time       time.Time
 31→	Steps      []traceStep
 32→}
 33→
 34→// parseTraceEntry parses a JSON log line into a traceEntry.
 35→// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
 36→func parseTraceEntry(line string) *traceEntry {
 37→	var raw map[string]json.RawMessage
 38→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 39→		return nil
 40→	}
 41→
 42→	// Check that msg == "perf"
 43→	var msg string
 44→	if msgRaw, ok := raw["msg"]; !ok {
 45→		return nil
 46→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 47→		return nil
 48→	}
 49→
 50→	entry := &traceEntry{}
 51→
 52→	// Best-effort field extraction: missing or mistyped fields keep their
 53→	// zero values rather than discarding the entire entry.
 54→	if opRaw, ok := raw["op"]; ok {
 55→		_ = json.Unmarshal(opRaw, &entry.Op)
 56→	}
 57→	if dRaw, ok := raw["duration_ms"]; ok {
 58→		_ = json.Unmarshal(dRaw, &entry.DurationMs)
 59→	}
 60→	if errRaw, ok := raw["error"]; ok {
 61→		_ = json.Unmarshal(errRaw, &entry.Error)
 62→	}
 63→
 64→	// Extract time
 65→	if tRaw, ok := raw["time"]; ok {
 66→		var ts string
 67→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 68→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 69→				entry.Time = parsed
 70→			}
 71→		}
 72→	}
 73→
 74→	// Extract steps by finding keys matching "steps.*_ms"
 75→	stepDurations := make(map[string]int64)
 76→	stepErrors := make(map[string]bool)
 77→
 78→	for key, val := range raw {
 79→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 80→			name := strings.TrimPrefix(key, "steps.")
 81→			name = strings.TrimSuffix(name, "_ms")
 82→
 83→			var ms int64
 84→			if err := json.Unmarshal(val, &ms); err == nil {
 85→				stepDurations[name] = ms
 86→			}
 87→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 88→			name := strings.TrimPrefix(key, "steps.")
 89→			name = strings.TrimSuffix(name, "_err")
 90→
 91→			var errFlag bool
 92→			if err := json.Unmarshal(val, &errFlag); err == nil {
 93→				stepErrors[name] = errFlag
 94→			}
 95→		}
 96→	}
 97→
 98→	// Separate parent steps from sub-steps.
 99→	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
100→	// and the last segment is a non-negative integer.
101→	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
102→	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
103→	parentStepDurations := make(map[string]int64)
104→	parentStepErrors := make(map[string]bool)
105→
106→	for name, ms := range stepDurations {
107→		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
108→			if subStepDurations[parent] == nil {
109→				subStepDurations[parent] = make(map[int]int64)
110→			}
111→			subStepDurations[parent][idx] = ms
112→			if stepErrors[name] {
113→				if subStepErrors[parent] == nil {
114→					subStepErrors[parent] = make(map[int]bool)
115→				}
116→				subStepErrors[parent][idx] = true
117→			}
118→		} else {
119→			parentStepDurations[name] = ms
120→			parentStepErrors[name] = stepErrors[name]
121→		}
122→	}
123→
124→	// Build steps slice sorted alphabetically by name
125→	steps := make([]traceStep, 0, len(parentStepDurations))
126→	for name, ms := range parentStepDurations {
127→		step := traceStep{
128→			Name:       name,
129→			DurationMs: ms,
130→			Error:      parentStepErrors[name],
131→		}
132→
133→		// Attach sub-steps if any, sorted by numeric index
134→		if subs, ok := subStepDurations[name]; ok {
135→			indices := make([]int, 0, len(subs))
136→			for idx := range subs {
137→				indices = append(indices, idx)
138→			}
139→			sort.Ints(indices)
140→
141→			subList := make([]traceStep, 0, len(subs))
142→			for _, idx := range indices {
143→				subList = append(subList, traceStep{
144→					Name:       fmt.Sprintf("%s.%d", name, idx),
145→					DurationMs: subs[idx],
146→					Error:      subStepErrors[name][idx],
147→				})
148→			}
149→			step.SubSteps = subList
150→		}
151→
152→		steps = append(steps, step)
153→	}
154→	sort.Slice(steps, func(i, j int) bool {
155→		return steps[i].Name < steps[j].Name
156→	})
157→
158→	entry.Steps = steps
159→
160→	return entry
161→}
162→
163→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
164→// Returns the parent name, index, and true if it is a sub-step.
165→// A name is a sub-step if: the last segment after the final "." is a non-negative
166→// integer AND the parent name exists in allSteps.
167→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
168→	lastDot := strings.LastIndex(name, ".")
169→	if lastDot < 0 {
170→		return "", 0, false
171→	}
172→	parent := name[:lastDot]
173→	suffix := name[lastDot+1:]
174→	idx, err := strconv.Atoi(suffix)
175→	if err != nil || idx < 0 {
176→		return "", 0, false
177→	}
178→	if _, exists := allSteps[parent]; !exists {
179→		return "", 0, false
180→	}
181→	return parent, idx, true
182→}
183→
184→// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
185→// ordered newest first. If hookFilter is non-empty, only entries with a matching
186→// Op field are included.
187→func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
188→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
189→	if err != nil {
190→		if errors.Is(err, os.ErrNotExist) {
191→			return nil, nil
192→		}
193→		return nil, fmt.Errorf("opening log file: %w", err)
194→	}
195→	defer f.Close()
196→
197→	var entries []traceEntry
198→
199→	scanner := bufio.NewScanner(f)
200→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
201→	for scanner.Scan() {
202→		entry := parseTraceEntry(scanner.Text())
203→		if entry == nil {
204→			continue
205→		}
206→		if hookFilter != "" && entry.Op != hookFilter {
207→			continue
208→		}
209→		entries = append(entries, *entry)
210→	}
211→
212→	if err := scanner.Err(); err != nil {
213→		return nil, fmt.Errorf("reading log file: %w", err)
214→	}
215→
216→	// Take the last N entries
217→	if len(entries) > last {
218→		entries = entries[len(entries)-last:]
219→	}
220→
221→	// Reverse so newest entries are first
222→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
223→		entries[i], entries[j] = entries[j], entries[i]
224→	}
225→
226→	return entries, nil
227→}
228→
229→// renderTraceEntries writes a formatted table of trace entries to w.
230→// If entries is empty, it prints a help message about enabling traces.
231→func renderTraceEntries(w io.Writer, entries []traceEntry) {
232→	if len(entries) == 0 {
233→		fmt.Fprintln(w, "No trace entries found.")
234→		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
235→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
236→		return
237→	}
238→
239→	for i, entry := range entries {
240→		if i > 0 {
241→			fmt.Fprintln(w)
242→		}
243→
244→		// Header line: op  duration  [timestamp]
245→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
246→		if !entry.Time.IsZero() {
247→			header += "  " + entry.Time.Format(time.RFC3339)
248→		}
249→		fmt.Fprintln(w, header)
250→		fmt.Fprintln(w)
251→
252→		if len(entry.Steps) == 0 {
253→			continue
254→		}
255→
256→		// Compute max name display width (at least len("STEP")).
257→		// Sub-steps are indented 5 extra display columns relative to parent rows
258→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
259→		const subExtraIndent = 5
260→		nameWidth := len("STEP")
261→		for _, s := range entry.Steps {
262→			if len(s.Name) > nameWidth {
263→				nameWidth = len(s.Name)
264→			}
265→			for _, sub := range s.SubSteps {
266→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
267→					nameWidth = needed
268→				}
269→			}
270→		}
271→
272→		// Column header
273→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
274→
275→		// Step rows
276→		for _, s := range entry.Steps {
277→			dur := fmt.Sprintf("%dms", s.DurationMs)
278→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
279→			if s.Error {
280→				line += "  x"
281→			}
282→			fmt.Fprintln(w, line)
283→
284→			// Sub-step rows with ASCII tree connectors.
285→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
286→			// (├─, └─) breaking Go's byte-based %-*s alignment.
287→			for i, sub := range s.SubSteps {
288→				connector := "├─"
289→				if i == len(s.SubSteps)-1 {
290→					connector = "└─"
291→				}
292→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
293→				pad := nameWidth - subExtraIndent - len(sub.Name)
294→				if pad < 0 {
295→					pad = 0
296→				}
297→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
298→				if sub.Error {
299→					subLine += "  x"
300→				}
301→				fmt.Fprintln(w, subLine)
302→			}
303→		}
304→	}
305→}
