		return "", 0, false
	}
	parent := name[:lastDot]
	suffix := name[lastDot+1:]
	idx, err := strconv.Atoi(suffix)
	if err != nil || idx < 0 {
		return "", 0, false
	}
	if _, exists := allSteps[parent]; !exists {
		return "", 0, false
	}
	return parent, idx, true
