 923→+
 924→+// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
 925→+// creates a child span representing one pass through the loop.
 926→+//
 927→+// Usage:
 928→+//
 929→+//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
 930→+//	for _, item := range items {
 931→+//	    iterCtx, iterSpan := loop.Iteration(ctx)
 932→+//	    doWork(iterCtx, item)
 933→+//	    iterSpan.End()
 934→+//	}
 935→+//	loop.End()
 936→+type LoopSpan struct {
 937→+	span *Span
 938→+}
 939→+
 940→+// StartLoop begins a new loop span. The returned context contains the loop span
 941→+// and should be passed to Iteration. Call loop.End() after the loop completes.
 942→+func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
 943→+	ctx, s := Start(ctx, name, attrs...)
 944→+	return ctx, &LoopSpan{span: s}
 945→+}
 946→+
 947→+// Iteration creates a child span for a single loop iteration. The caller must
 948→+// call End() on the returned span when the iteration completes.
 949→+func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
 950→+	return Start(ctx, l.span.name)
 951→+}
 952→+
 953→+// End completes the loop span, auto-ending any unended iteration children first
 954→+// so their durations are captured at loop-end time rather than deferring to the
 955→+// root span's End() (which may run much later).
 956→+func (l *LoopSpan) End() {
 957→+	for _, child := range l.span.children {
 958→+		if !child.ended {
 959→+			child.End()
 960→+		}
 961→+	}
 962→+	l.span.End()
 963→+}
