  1→package cli
  2→
  3→import (
  4→	"bufio"
  5→	"cmp"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"io"
 10→	"os"
 11→	"slices"
 12→	"strconv"
 13→	"strings"
 14→	"time"
 15→)
 16→
 17→// traceStep represents a single timed step within a trace span.
 18→// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
 19→type traceStep struct {
 20→	Name       string
 21→	DurationMs int64
 22→	Error      bool
 23→	SubSteps   []traceStep
 24→}
 25→
 26→// traceEntry represents a parsed performance trace log entry.
 27→type traceEntry struct {
 28→	Op         string
 29→	DurationMs int64
 30→	Error      bool
 31→	Time       time.Time
 32→	Steps      []traceStep
 33→}
 34→
 35→// parseTraceEntry parses a JSON log line into a traceEntry.
 36→// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
 37→func parseTraceEntry(line string) *traceEntry {
 38→	// Cheap pre-filter: skip full JSON parse for lines that can't be perf entries.
 39→	// Most lines in the shared log file are non-perf, so this avoids the
 40→	// marshalling cost for the common reject path.
 41→	if !strings.Contains(line, `"msg":"perf"`) {
 42→		return nil
 43→	}
 44→
 45→	var raw map[string]json.RawMessage
 46→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 47→		return nil
 48→	}
 49→
 50→	// Verify msg == "perf" after full parse (the pre-filter could match substrings)
 51→	var msg string
 52→	if msgRaw, ok := raw["msg"]; !ok {
 53→		return nil
 54→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 55→		return nil
 56→	}
 57→
 58→	entry := &traceEntry{}
 59→
 60→	// Best-effort field extraction: missing or mistyped fields keep their
 61→	// zero values rather than discarding the entire entry.
 62→	if opRaw, ok := raw["op"]; ok {
 63→		_ = json.Unmarshal(opRaw, &entry.Op)
 64→	}
 65→	if dRaw, ok := raw["duration_ms"]; ok {
 66→		_ = json.Unmarshal(dRaw, &entry.DurationMs)
 67→	}
 68→	if errRaw, ok := raw["error"]; ok {
 69→		_ = json.Unmarshal(errRaw, &entry.Error)
 70→	}
 71→
 72→	// Extract time
 73→	if tRaw, ok := raw["time"]; ok {
 74→		var ts string
 75→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 76→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 77→				entry.Time = parsed
 78→			}
 79→		}
 80→	}
 81→
 82→	// Extract steps by finding keys matching "steps.*_ms"
 83→	stepDurations := make(map[string]int64)
 84→	stepErrors := make(map[string]bool)
 85→
 86→	for key, val := range raw {
 87→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 88→			name := strings.TrimPrefix(key, "steps.")
 89→			name = strings.TrimSuffix(name, "_ms")
 90→
 91→			var ms int64
 92→			if err := json.Unmarshal(val, &ms); err == nil {
 93→				stepDurations[name] = ms
 94→			}
 95→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 96→			name := strings.TrimPrefix(key, "steps.")
 97→			name = strings.TrimSuffix(name, "_err")
 98→
 99→			var errFlag bool
100→			if err := json.Unmarshal(val, &errFlag); err == nil {
101→				stepErrors[name] = errFlag
102→			}
103→		}
104→	}
105→
106→	// Separate parent steps from sub-steps.
107→	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
108→	// and the last segment is a non-negative integer.
109→	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
110→	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
111→	parentStepDurations := make(map[string]int64)
112→	parentStepErrors := make(map[string]bool)
113→
114→	for name, ms := range stepDurations {
115→		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
116→			if subStepDurations[parent] == nil {
117→				subStepDurations[parent] = make(map[int]int64)
118→			}
119→			subStepDurations[parent][idx] = ms
120→			if stepErrors[name] {
121→				if subStepErrors[parent] == nil {
122→					subStepErrors[parent] = make(map[int]bool)
123→				}
124→				subStepErrors[parent][idx] = true
125→			}
126→		} else {
127→			parentStepDurations[name] = ms
128→			parentStepErrors[name] = stepErrors[name]
129→		}
130→	}
131→
132→	// Build steps slice sorted alphabetically by name
133→	steps := make([]traceStep, 0, len(parentStepDurations))
134→	for name, ms := range parentStepDurations {
135→		step := traceStep{
136→			Name:       name,
137→			DurationMs: ms,
138→			Error:      parentStepErrors[name],
139→		}
140→
141→		// Attach sub-steps if any, sorted by numeric index
142→		if subs, ok := subStepDurations[name]; ok {
143→			indices := make([]int, 0, len(subs))
144→			for idx := range subs {
145→				indices = append(indices, idx)
146→			}
147→			slices.Sort(indices)
148→
149→			subList := make([]traceStep, 0, len(subs))
150→			for _, idx := range indices {
151→				subList = append(subList, traceStep{
152→					Name:       fmt.Sprintf("%s.%d", name, idx),
153→					DurationMs: subs[idx],
154→					Error:      subStepErrors[name][idx],
155→				})
156→			}
157→			step.SubSteps = subList
158→		}
159→
160→		steps = append(steps, step)
161→	}
162→	slices.SortFunc(steps, func(a, b traceStep) int {
163→		return cmp.Compare(a.Name, b.Name)
164→	})
165→
166→	entry.Steps = steps
167→
168→	return entry
169→}
170→
171→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
172→// Returns the parent name, index, and true if it is a sub-step.
173→// A name is a sub-step if: the last segment after the final "." is a non-negative
174→// integer AND the parent name exists in allSteps.
175→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
176→	lastDot := strings.LastIndex(name, ".")
177→	if lastDot < 0 {
178→		return "", 0, false
179→	}
180→	parent := name[:lastDot]
181→	suffix := name[lastDot+1:]
182→	idx, err := strconv.Atoi(suffix)
183→	if err != nil || idx < 0 {
184→		return "", 0, false
185→	}
186→	if _, exists := allSteps[parent]; !exists {
187→		return "", 0, false
188→	}
189→	return parent, idx, true
190→}
191→
192→// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
193→// ordered newest first. If hookFilter is non-empty, only entries with a matching
194→// Op field are included.
195→func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
196→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
197→	if err != nil {
198→		if errors.Is(err, os.ErrNotExist) {
199→			return nil, nil
200→		}
201→		return nil, fmt.Errorf("opening log file: %w", err)
202→	}
203→	defer f.Close()
204→
205→	var entries []traceEntry
206→
207→	scanner := bufio.NewScanner(f)
208→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
209→	for scanner.Scan() {
210→		entry := parseTraceEntry(scanner.Text())
211→		if entry == nil {
212→			continue
213→		}
214→		if hookFilter != "" && entry.Op != hookFilter {
215→			continue
216→		}
217→		entries = append(entries, *entry)
218→	}
219→
220→	if err := scanner.Err(); err != nil {
221→		return nil, fmt.Errorf("reading log file: %w", err)
222→	}
223→
224→	// Take the last N entries
225→	if len(entries) > last {
226→		entries = entries[len(entries)-last:]
227→	}
228→
229→	// Reverse so newest entries are first
230→	slices.Reverse(entries)
231→
232→	return entries, nil
233→}
234→
235→// renderTraceEntries writes a formatted table of trace entries to w.
236→// If entries is empty, it prints a help message about enabling traces.
237→func renderTraceEntries(w io.Writer, entries []traceEntry) {
238→	if len(entries) == 0 {
239→		fmt.Fprintln(w, "No trace entries found.")
240→		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
241→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
242→		return
243→	}
244→
245→	for i, entry := range entries {
246→		if i > 0 {
247→			fmt.Fprintln(w)
248→		}
249→
250→		// Header line: op  duration  [timestamp]
251→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
252→		if !entry.Time.IsZero() {
253→			header += "  " + entry.Time.Format(time.RFC3339)
254→		}
255→		fmt.Fprintln(w, header)
256→		fmt.Fprintln(w)
257→
258→		if len(entry.Steps) == 0 {
259→			continue
260→		}
261→
262→		// Compute max name display width (at least len("STEP")).
263→		// Sub-steps are indented 5 extra display columns relative to parent rows
264→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
265→		const subExtraIndent = 5
266→		nameWidth := len("STEP")
267→		for _, s := range entry.Steps {
268→			if len(s.Name) > nameWidth {
269→				nameWidth = len(s.Name)
270→			}
271→			for _, sub := range s.SubSteps {
272→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
273→					nameWidth = needed
274→				}
275→			}
276→		}
277→
278→		// Column header
279→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
280→
281→		// Step rows
282→		for _, s := range entry.Steps {
283→			dur := fmt.Sprintf("%dms", s.DurationMs)
284→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
285→			if s.Error {
286→				line += "  x"
287→			}
288→			fmt.Fprintln(w, line)
289→
290→			// Sub-step rows with ASCII tree connectors.
291→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
292→			// (├─, └─) breaking Go's byte-based %-*s alignment.
293→			for i, sub := range s.SubSteps {
294→				connector := "├─"
295→				if i == len(s.SubSteps)-1 {
296→					connector = "└─"
297→				}
298→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
299→				pad := nameWidth - subExtraIndent - len(sub.Name)
300→				if pad < 0 {
301→					pad = 0
302→				}
303→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
304→				if sub.Error {
305→					subLine += "  x"
306→				}
307→				fmt.Fprintln(w, subLine)
308→			}
309→		}
310→	}
311→}
